#!/bin/bash
# End-to-end driver for ReMoVe. The input is a coarse video generated by Wan2.2.
#
# Usage:
#   ./run_pipeline.sh --video examples/lunges/coarse.mp4 --prompt "..." \
#     --head examples/lunges/head.jpg --work outputs/lunges
set -euo pipefail
source "$(dirname "$0")/env.sh"
S="$REMOVE_ROOT/scripts"

PROMPT=""; HEAD=""; WORK=""; VIDEO=""; FORCE=""; GPU9=0; GEN=1; FRAMES9=auto
PARALLEL_PREP=0; PREP_GPUS=""
while [ $# -gt 0 ]; do
  case "$1" in
    --prompt) PROMPT="$2"; shift 2 ;;
    --head) HEAD="$2"; shift 2 ;;
    --work) WORK="$2"; shift 2 ;;
    --video) VIDEO="$2"; shift 2 ;;
    --force-high) FORCE=--force-high; shift ;;
    --gpu) GPU9="$2"; shift 2 ;;
    --frames) FRAMES9="$2"; shift 2 ;;
    --no-generate) GEN=0; shift ;;
    --parallel-prep) PARALLEL_PREP=1; shift ;;
    --prep-gpus) PREP_GPUS="$2"; shift 2 ;;
    *) echo "unknown arg $1" >&2; exit 1 ;;
  esac
done
[ -n "$PROMPT" ] && [ -n "$HEAD" ] && [ -n "$WORK" ] && [ -n "$VIDEO" ] || {
  echo "need --video, --prompt, --head, and --work" >&2
  exit 1
}
V="$(readlink -f "$VIDEO")"
HEAD="$(readlink -f "$HEAD")"
WORK="$(readlink -f "$WORK")"
[ -f "$V" ] || { echo "video not found: $V" >&2; exit 1; }
[ -f "$HEAD" ] || { echo "head image not found: $HEAD" >&2; exit 1; }
mkdir -p "$WORK"
NAME="$(basename "$V")"; NAME="${NAME%.*}"
echo "### work dir: $WORK   sample: $NAME"

if [ "$PARALLEL_PREP" = 1 ]; then
  IFS=',' read -r GPU2 GPU3A GPU3B GPU4 <<< "$PREP_GPUS"
  [ -n "$GPU2" ] && [ -n "$GPU3A" ] && [ -n "$GPU3B" ] && [ -n "$GPU4" ] || {
    echo "--parallel-prep requires --prep-gpus GPU2,GPU3A,GPU3B,GPU4" >&2; exit 1; }
  (CUDA_VISIBLE_DEVICES="$GPU2" bash "$S/pipeline/gvhmr.sh" "$V" "$WORK/gvhmr") & P2=$!
  (CUDA_VISIBLE_DEVICES="$GPU3A" bash "$S/pipeline/remove_person.sh" "$V" "$WORK/segmentation") & P3A=$!
  (CUDA_VISIBLE_DEVICES="$GPU3B" bash "$S/pipeline/extract_depth.sh" "$V" "$WORK/depth") & P3B=$!
  (CUDA_VISIBLE_DEVICES="$GPU4" bash "$S/pipeline/reference_image.sh" "$HEAD" "$WORK/reference") & P4=$!
  wait "$P2"
  bash "$S/pipeline/select_constraints.sh" "$WORK/gvhmr" "$WORK/constraints" $FORCE
  wait "$P3A"; wait "$P3B"; wait "$P4"
else
  bash "$S/pipeline/gvhmr.sh" "$V" "$WORK/gvhmr"
  bash "$S/pipeline/remove_person.sh" "$V" "$WORK/segmentation"
  bash "$S/pipeline/extract_depth.sh" "$V" "$WORK/depth"
  bash "$S/pipeline/reference_image.sh" "$HEAD" "$WORK/reference"
  bash "$S/pipeline/select_constraints.sh" "$WORK/gvhmr" "$WORK/constraints" $FORCE
fi

TGT="$WORK/gvhmr/$NAME/hmr4d_results.pt"
HSTEM="$(basename "$HEAD")"; HSTEM="${HSTEM%.*}"
REF="$WORK/reference/gvhmr/${HSTEM}_5frames/hmr4d_results.pt"
TIER="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))[sys.argv[2]])' "$WORK/constraints/constraints/tiers.json" "$NAME")"

MOTION="$(bash "$S/kimodo/generate_motion.sh" "$PROMPT" "$WORK/constraints/constraints/$NAME.json" "$WORK/kimodo/$NAME.npz" "$TIER" | tail -n 1)"
bash "$S/render/render_mesh_video.sh" "$MOTION" "$TGT" "$HEAD" "$REF" "$WORK/mesh/$NAME.mp4"
bash "$S/pipeline/fuse_depth.sh" "$V" "$WORK/mesh/$NAME.mp4" "$WORK/depth/${NAME}_depth_maps.npz" "$WORK/segmentation/${NAME}_mask.mp4" "$WORK/depth_fusion"

if [ "$GEN" = 1 ]; then
  IMG9="$WORK/${NAME}_frame0.jpg"
  [ -f "$IMG9" ] || "$FFMPEG" -y -loglevel error -i "$V" -frames:v 1 -q:v 2 "$IMG9"
  FRAMES="$FRAMES9" bash "$S/wan/generate_video.sh" "$IMG9" "$PROMPT" "$WORK/mesh/$NAME.mp4" "$WORK/depth_fusion/final_mesh_fused_depth_turbo.mp4" "$WORK/wan" "$GPU9"
fi

echo "### DONE"
echo "  mesh video : $WORK/mesh/$NAME.mp4"
echo "  depth video: $WORK/depth_fusion/final_mesh_fused_depth_turbo.mp4"
[ "$GEN" = 1 ] && echo "  final video: $WORK/wan/remove_wan.mp4"
